<script setup lang="ts">
import { computed, inject, onBeforeUnmount, onMounted, ref, watch, type Ref } from 'vue';
import { onBeforeRouteLeave, useRoute } from 'vue-router';
import { displayTime, downloadFile, errorMessage, hours, statusLabel, today } from '@worktime/api-client';
import { reporting, type Capabilities, type ExportJob, type Report } from '../../shared/reporting';
const route=useRoute();
const props=defineProps<{section:string}>();const kind=ref(props.section==='workload'?'workload':props.section==='onsite'?'onsite':'project-costs'),busy=ref(false),error=ref(''),notice=ref(''),caps=ref<Capabilities>(),report=ref<Report>(),exports=ref<ExportJob[]>([]);
const loadedQuery=ref('');
const from=ref(today().slice(0,7)+'-01'),to=ref(today()),mode=ref('CURRENT'),versionIds=ref(''),userId=ref(''),workItemId=ref(''),departmentId=ref(''),level=ref(''),grain=ref('WEEK');
const sharedBusy=inject<Ref<boolean>>('operationBusy');watch(busy,v=>{if(sharedBusy)sharedBusy.value=v;});
const title=computed(()=>props.section==='workload'?'人员工时分析':props.section==='onsite'?'现场统计':'项目投入与成本');
const labels:Record<string,string>={employeeNo:'工号',name:'姓名或名称',departmentName:'部门',levelCode:'职级',periodStart:'开始日期',periodEnd:'结束日期',requiredMinutes:'应填工时',confirmedWorkMinutes:'已确认工作工时',confirmedProjectMinutes:'项目工时',confirmedNonProjectMinutes:'非项目工时',confirmedIdleMinutes:'待安排工作',leaveMinutes:'请假时长',overtimeMinutes:'超额工作工时',reportedMinutes:'已填工时',missingDays:'缺填天数',pendingCount:'未确认记录',loadPercent:'工作负荷率',complete:'数据已完整确认',status:'统计状态',expectedPersonDays:'应填人日',readyOnTimeDays:'按时填报人日',unresolvedCount:'未确认工时记录',timelyRatePercent:'填报及时率',lateSubmitPeople:'逾期提交人数',notSubmittedPeople:'到期未提交人数',approvalSubmitted:'到期应审批记录',approvalHandled:'已完成审批记录',approvalApproved:'审批通过记录',approvalRejected:'审批驳回记录',approvalCompletionPercent:'审批完成率',overduePackages:'超时审批单',code:'编码',type:'类型',pmName:'项目负责人',confirmedMinutes:'已确认工时',onsiteDays:'已确认现场天数',laborCost:'标准人工成本',onsiteCost:'标准现场成本',totalCost:'标准总成本',participants:'参与人数',date:'日期',workItemName:'项目或事项',reason:'原因说明',state:'状态',projectMinutes:'本项目工时',totalWorkMinutes:'当日总工作工时',ratioPercent:'本项目工时占比',ratioStatus:'占比状态',reviewRequired:'需核实时间分配',oaStatus:'出差单核对',oaComparedAt:'核对时间',oaNote:'核对说明',kind:'记录类型',recordId:'记录 ID',revisionId:'记录版本 ID',action:'操作',minutes:'工时',content:'工作内容',approvedAt:'确认时间',approvedByName:'实际审批人',costAmount:'标准成本',dailyRate:'每日成本标准',policyVersion:'计价规则版本',onsitePeople:'现场人数',confirmedDays:'已确认天数',ratioNumeratorMinutes:'纳入占比的项目工时',ratioDenominatorMinutes:'纳入占比的总工作工时',people:'人员数',reviewCount:'需核实时间分配天数'};
const tableFields:Record<string,string[]>={workload:['name','employeeNo','departmentName','levelCode','periodStart','periodEnd','requiredMinutes','confirmedWorkMinutes','confirmedProjectMinutes','confirmedNonProjectMinutes','confirmedIdleMinutes','leaveMinutes','overtimeMinutes','reportedMinutes','missingDays','pendingCount','loadPercent','status'],compliance:['name','employeeNo','expectedPersonDays','readyOnTimeDays','missingDays','unresolvedCount'],'project-costs':['code','name','departmentName','pmName','confirmedMinutes','onsiteDays','laborCost','onsiteCost','totalCost','participants','pendingCount'],onsite:['date','name','employeeNo','workItemName','reason','state','onsiteDays','onsiteCost','projectMinutes','totalWorkMinutes','ratioPercent','ratioStatus','reviewRequired','oaStatus','oaComparedAt','oaNote'],details:['date','name','employeeNo','departmentName','workItemName','kind','action','state','minutes','content','reason','approvedAt','approvedByName','costAmount','dailyRate','levelCode','policyVersion','recordId','revisionId']};
const columns=computed(()=>report.value?(tableFields[kind.value]??[]).filter(k=>report.value!.rows.some(r=>r[k]!==undefined)):[]);
function format(key:string,value:unknown){if(value===null||value===undefined)return '—';if(['laborCost','onsiteCost','totalCost','costAmount','dailyRate'].includes(key))return `¥${value}`;if(typeof value==='boolean')return value?'是':'否';if(key.endsWith('Minutes')||key==='minutes')return `${hours(Number(value))}h`;if(key.endsWith('Percent'))return `${value}%`;if(['generatedAt','oaComparedAt','approvedAt'].includes(key))return displayTime(String(value));if(typeof value==='object')return JSON.stringify(value);const dict:Record<string,string>={JUNIOR:'初级',MIDDLE:'中级',SENIOR:'高级',CONFIRMED:'已确认',INCOMPLETE:'待补全或确认',NO_BASE:'无应填工时',NOT_APPLICABLE:'不适用',NOT_COMPARED:'尚未核对',DATA_PENDING:'来源数据待核实',OA_NO_RECORD:'OA 无对应出差单',NOT_REPORTED:'OA 已批，现场未填',UNKNOWN:'数据完整性未核实',MATCHED:'一致',MISMATCH:'不一致',NO_ORDER:'无对应出差单',OA_ONLY:'OA 已批，现场待核实',TIME:'工时',ONSITE:'现场日',PROJECT:'项目',NON_PROJECT:'非项目',IDLE:'待安排工作',REPORT:'填报',MISSING:'缺填'};return dict[String(value)]??statusLabel(String(value));}
function query(){return {from:from.value,to:to.value,mode:mode.value,versionIds:mode.value==='FORMAL'?versionIds.value:'',userId:userId.value,workItemId:workItemId.value,departmentId:departmentId.value,level:level.value,grain:grain.value};}
async function load(){if(busy.value)return;busy.value=true;error.value='';try{report.value=await reporting.report(kind.value,query());loadedQuery.value=JSON.stringify(query());}catch(e){report.value=undefined;error.value=errorMessage(e);}finally{busy.value=false;}}
async function loadExports(){try{exports.value=await reporting.exports();}catch(e){error.value=errorMessage(e);}}
async function createExport(){busy.value=true;error.value='';try{const q=query();const filtered=Object.fromEntries(Object.entries(q).filter(([,value])=>value));const job=await reporting.export({...filtered,kind:kind.value,versionIds:q.versionIds?q.versionIds.split(',').map(v=>v.trim()):undefined});notice.value=`导出任务 ${job.id} 已创建，文件生成后可下载。`;await loadExports();}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
async function download(job:ExportJob){busy.value=true;error.value='';try{downloadFile(await reporting.download(job.id),`${title.value}-${job.id}.xlsx`);}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
function color(row:Record<string,unknown>){if(kind.value!=='workload'||row.status!=='CONFIRMED'||row.loadPercent==null)return '';const value=Number(row.loadPercent);return value<80?'load-low':value<=110?'load-normal':value<=130?'load-high':'load-red';}
async function changeKind(value:string){kind.value=value;await load();}
onMounted(async()=>{if(route.query.version&&route.query.month){const m=String(route.query.month);from.value=m+'-01';to.value=new Date(Date.UTC(Number(m.slice(0,4)),Number(m.slice(5)),0)).toISOString().slice(0,10);mode.value='FORMAL';versionIds.value=String(route.query.version);}try{caps.value=await reporting.capabilities();await load();await loadExports();}catch(e){error.value=errorMessage(e);}});onBeforeRouteLeave(()=>!busy.value);onBeforeUnmount(()=>{if(sharedBusy)sharedBusy.value=false;});
</script>
<template><div class="workflow-page"><div class="workflow-head"><div><h1>{{ title }}</h1><p>当前数据反映最新处理结果；正式月报保留发布时的数据，后续修改需发布新版才会更新月报。</p></div></div><nav class="workflow-tabs"><template v-if="section==='workload'"><button :class="{active:kind==='workload'}" :disabled="busy" @click="changeKind('workload')">工作负荷</button><button :class="{active:kind==='compliance'}" :disabled="busy" @click="changeKind('compliance')">填报与审批</button></template><template v-else-if="section==='costs'"><button :class="{active:kind==='project-costs'}" :disabled="busy" @click="changeKind('project-costs')">项目汇总</button><button :class="{active:kind==='details'}" :disabled="busy" @click="changeKind('details')">工时与成本明细</button></template></nav><form class="workflow-filters" @submit.prevent="load"><label>开始日期<input v-model="from" required type="date" :disabled="busy" /></label><label>结束日期<input v-model="to" required type="date" :disabled="busy" /></label><label>数据版本<select aria-label="数据版本" v-model="mode" :disabled="busy"><option value="CURRENT">当前数据</option><option value="FORMAL">正式月报</option></select></label><label v-if="mode==='FORMAL'">月报版本 ID<input v-model="versionIds" placeholder="留空使用每月最新版；多个 ID 用逗号分隔" :disabled="busy" /></label><label>人员<select aria-label="人员" v-model="userId" :disabled="busy"><option value="">全部可查看人员</option><option v-for="u in caps?.users" :key="u.id" :value="u.id">{{ u.name }} / {{ u.employeeNo }}</option></select></label><label>项目<select aria-label="项目" v-model="workItemId" :disabled="busy"><option value="">全部可查看项目</option><option v-for="w in caps?.projects" :key="w.id" :value="w.id">{{ w.name }}</option></select></label><label>部门<select aria-label="部门" v-model="departmentId" :disabled="busy"><option value="">全部可查看部门</option><option v-for="d in caps?.departments" :key="d.id" :value="d.id">{{ d.name }}</option></select></label><label v-if="kind==='workload'">统计周期<select aria-label="统计周期" v-model="grain" :disabled="busy"><option value="WEEK">自然周</option><option value="DAY">每日</option></select></label><button class="primary" :disabled="busy">{{ busy?'查询中…':'查询' }}</button></form><p v-if="error" class="workflow-error" role="alert">{{ error }}</p><p v-if="notice" class="workflow-success">{{ notice }}</p><template v-if="report"><p class="workflow-note">{{ report.mode==='FORMAL'?'正式月报':'当前数据' }} · {{ report.from }} 至 {{ report.to }} · 生成于 {{ displayTime(report.generatedAt) }}</p><p v-if="report.missingMonths.length" class="workflow-warning">以下月份尚无正式版本：{{ report.missingMonths.join('、') }}，本次结果不包含这些月份。</p><p v-if="report.versions.length">采用版本：{{ report.versions.map(v=>`${v.month} V${v.versionNo}（ID ${v.id}）`).join('，') }}</p><div class="workflow-metrics"><div v-for="(value,key) in report.summary" :key="key"><span>{{ labels[key]??key }}</span><strong>{{ format(key,value) }}</strong></div></div><p v-if="kind==='workload'" class="workflow-note">工作负荷率 = 已确认工作工时 ÷ 应填工时，不含待安排工作和请假时长。数据完整确认且应填工时大于 0 时才显示颜色：低于 80% 为蓝色，80% 至 110% 为绿色，超过 110% 至 130% 为黄色，超过 130% 为红色。</p><p v-if="kind==='compliance'" class="workflow-note">填报及时率按首次完整填写时间计算，每人每天算 1 人日。审批完成率仅统计已到审批期限的记录，通过和驳回均算完成。未确认记录包括未提交、待审批、驳回未处理及争议未解决的记录。</p><p v-if="section==='costs'" class="workflow-note">成本按统一标准计算，用于项目分析，不代表实际工资或报销金额。未确认记录包括未提交、待审批、驳回未处理和争议未解决的记录，暂不计入已确认成本。</p><p v-if="kind==='onsite'" class="workflow-note">本项目工时占比 = 本项目工时 ÷ 当日总工作工时。当天工时和现场记录均已完整确认、总工作工时大于 0 时才计算；低于 50% 提示核实时间分配。OA 出差数据确认完整后，才能判断是否有对应出差单。</p><section class="workflow-panel"><div class="workflow-between"><h2>{{ report.rows.length }} 条记录</h2><button :disabled="busy||loadedQuery!==JSON.stringify(query())" @click="createExport">导出 Excel</button></div><div v-if="!report.rows.length" class="workflow-empty">没有符合条件的数据。</div><div v-else class="workflow-table-wrap"><table class="workflow-table"><thead><tr><th v-for="column in columns" :key="column" :data-field="column">{{ labels[column] }}</th></tr></thead><tbody><tr v-for="(row,index) in report.rows" :key="index"><td v-for="column in columns" :key="column" :data-field="column" :class="column==='loadPercent'?color(row):''">{{ format(column,row[column]) }}</td></tr></tbody></table></div></section><details v-if="report.details.length"><summary>缺填、超时与未确认记录 {{ report.details.length }} 条</summary><article v-for="(row,index) in report.details" :key="index" class="workflow-panel"><span v-for="(value,key) in row" :key="key">{{ labels[key]??key }}：{{ format(key,value) }}　</span></article></details></template><section class="workflow-panel"><div class="workflow-between"><h2>我的导出任务</h2><button :disabled="busy" @click="loadExports">刷新任务</button></div><p class="workflow-note">文件生成后可在此下载，有效期 7 天。如查看权限已变更，请重新导出。</p><p v-if="!exports.length">暂无导出任务。</p><div v-for="job in exports" :key="job.id" class="workflow-between export-row"><span>任务 {{ job.id }} · {{ ({QUEUED:'排队中',RUNNING:'生成中',SUCCEEDED:'已生成',FAILED:'生成失败'} as Record<string,string>)[job.state]??job.state }} · {{ displayTime(job.createdAt) }}<small v-if="job.error"> {{ job.error }}</small></span><button v-if="job.state==='SUCCEEDED'" :disabled="busy" @click="download(job)">下载 Excel</button></div></section></div></template>
<style scoped>
.export-row { padding: var(--ts-space-12) 0; border-bottom: 1px solid var(--ts-color-divider); }
.load-low { background: var(--ts-color-primary-soft); color: var(--ts-color-primary-text); }
.load-normal { background: var(--ts-color-success-soft); color: var(--ts-color-success); }
.load-high { background: var(--ts-color-warning-soft); color: var(--ts-color-warning); }
.load-red { background: var(--ts-color-danger-soft); color: var(--ts-color-danger); }
.workflow-table :is(th, td):is([data-field$="Minutes"], [data-field$="Cost"], [data-field$="Percent"], [data-field$="Count"], [data-field$="Days"], [data-field="minutes"], [data-field="costAmount"], [data-field="dailyRate"], [data-field="participants"]) { text-align: right; white-space: nowrap; }
</style>
